"""Build the self-contained GitHub Pages laboratory from joint-SSM artifacts."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd


ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "data"


def records(path: Path) -> str:
    return json.dumps(pd.read_csv(path).to_dict(orient="records"), separators=(",", ":"))


def main() -> None:
    payload = {
        "__CELLS__": records(DATA / "joint_cell_summary.csv"),
        "__PAIRS__": records(DATA / "joint_paired_effects.csv"),
        "__TRACE__": records(DATA / "joint_example_trace.csv"),
        "__EFFECTS__": records(DATA / "joint_factorial_effects.csv"),
        "__META__": json.dumps(json.loads((DATA / "joint_experiment_metadata.json").read_text()), separators=(",", ":")),
    }
    template = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Executed joint torus-valued state-space benchmark for blind de-mixing of overlapping frequency-hopping emitters."><title>Signals Project · Executed Joint Torus SSM</title><link rel="preconnect" href="https://cdn.jsdelivr.net"><script src="https://cdn.jsdelivr.net/npm/plotly.js-dist-min@2.35.2/plotly.min.js"></script>
<style>
:root{--bg:#050810;--panel:#0d1521;--line:#24364a;--ink:#e8f1fb;--muted:#98aabd;--cyan:#38d6ff;--amber:#ffc35c;--violet:#ae91ff;--green:#65e6aa;--coral:#ff8178;--shadow:0 18px 50px rgba(0,0,0,.30)}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 82% -12%,#18344b 0,transparent 30%),linear-gradient(180deg,#050810,#08111b 56%,#050810);color:var(--ink);font:15px/1.6 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--cyan)}button,select{font:inherit}.shell{max-width:1280px;margin:auto;padding:0 24px 72px}.top{position:sticky;top:0;z-index:20;background:rgba(5,8,16,.88);backdrop-filter:blur(18px);border-bottom:1px solid rgba(160,190,220,.16)}.topin{max-width:1280px;margin:auto;padding:13px 24px;display:flex;align-items:center;gap:18px}.brand{font-weight:850;letter-spacing:.03em;white-space:nowrap}.brand b{color:var(--cyan)}nav{display:flex;gap:5px;overflow:auto}.tab{border:0;background:transparent;color:var(--muted);padding:9px 11px;border-radius:9px;cursor:pointer;white-space:nowrap}.tab:hover,.tab.active{background:#14283a;color:#fff}.reporttop{margin-left:auto;text-decoration:none;border:1px solid #32637a;padding:8px 12px;border-radius:9px;white-space:nowrap}.hero{padding:68px 0 36px;display:grid;grid-template-columns:1.35fr .65fr;gap:34px;align-items:end}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase;color:var(--cyan);font-weight:800}.hero h1{font-size:clamp(40px,6vw,76px);line-height:.98;letter-spacing:-.055em;margin:11px 0 20px;max-width:900px}.hero p{font-size:18px;color:#bac8d7;max-width:810px}.scope{padding:18px;border:1px solid #654f27;border-left:4px solid var(--amber);background:rgba(255,195,92,.07);border-radius:0 12px 12px 0;color:#ead8b5}.scope strong{color:var(--amber)}.view{display:none}.view.active{display:block}.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:13px;margin:12px 0 28px}.card,.panel{background:linear-gradient(145deg,rgba(17,29,43,.96),rgba(10,18,28,.96));border:1px solid var(--line);box-shadow:var(--shadow);border-radius:16px}.card{padding:17px}.kval{font-size:28px;font-weight:850;letter-spacing:-.035em}.klabel{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}.panel{padding:24px;margin:18px 0}.panel h2{margin:0 0 5px;font-size:25px}.panel h3{margin:0 0 7px}.sub{color:var(--muted);margin:0 0 18px}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.method{padding:19px;border:1px solid var(--line);border-radius:13px;background:rgba(5,10,17,.48)}.tag{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--cyan)}.method p,.method li{color:#b5c2d0}.chart{height:500px}.chart.short{height:390px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:8px 0 14px}.control{display:grid;gap:5px;color:var(--muted);font-size:11px;letter-spacing:.09em;text-transform:uppercase}.control select{min-width:175px;color:var(--ink);background:#08111c;border:1px solid #334b63;border-radius:9px;padding:9px 12px}.pipeline{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.node{position:relative;min-height:150px;padding:16px;border:1px solid var(--line);border-radius:12px;background:#0a131f}.node:not(:last-child):after{content:'→';position:absolute;right:-13px;top:52px;color:var(--cyan);font-size:22px;z-index:2}.node b{display:block;margin:5px 0}.node small{color:var(--muted)}.formula{font:15px/1.55 Georgia,serif;background:#07111b;border:1px solid #24435b;border-radius:11px;padding:15px;overflow:auto;color:#daebfb}.status{display:inline-flex;align-items:center;gap:7px;padding:4px 9px;border-radius:999px;background:rgba(101,230,170,.11);color:var(--green);font-size:12px}.status.pending{background:rgba(255,195,92,.10);color:var(--amber)}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{padding:10px;border-bottom:1px solid #25364a;text-align:right}th{font-size:11px;letter-spacing:.07em;text-transform:uppercase;color:var(--muted)}th:first-child,td:first-child{text-align:left}.scroll{overflow:auto}.download{display:inline-flex;text-decoration:none;color:#06111a;background:var(--cyan);font-weight:850;padding:12px 16px;border-radius:10px;margin:0 8px 9px 0}.download.secondary{background:transparent;color:var(--ink);border:1px solid #405970}.steps{counter-reset:item;display:grid;gap:12px}.step{display:grid;grid-template-columns:36px 1fr;gap:12px}.step:before{counter-increment:item;content:counter(item);width:31px;height:31px;border-radius:50%;display:grid;place-items:center;background:#163149;color:var(--cyan);font-weight:850}.fine{font-size:12px;color:#8295a8}.footer{border-top:1px solid var(--line);margin-top:42px;padding-top:28px;color:var(--muted)}.noscript{margin:18px;padding:15px;border:1px solid var(--coral);background:#291416}@media(max-width:980px){.hero{grid-template-columns:1fr}.kpis{grid-template-columns:repeat(3,1fr)}.pipeline{grid-template-columns:1fr 1fr}.node:after{display:none}.grid2,.grid3{grid-template-columns:1fr}.topin{flex-wrap:wrap}.reporttop{margin-left:0}}@media(max-width:580px){.shell,.topin{padding-left:14px;padding-right:14px}.hero{padding-top:42px}.kpis{grid-template-columns:1fr 1fr}.pipeline{grid-template-columns:1fr}.panel{padding:16px}.chart{height:420px}.kval{font-size:24px}}
</style></head><body><noscript><div class="noscript">JavaScript is required for the interactive graphs. The PDF and CSV evidence remain available from the repository.</div></noscript>
<header class="top"><div class="topin"><div class="brand"><b>◉</b> SIGNALS PROJECT</div><nav aria-label="Research sections"><button class="tab active" data-view="overview">Overview</button><button class="tab" data-view="factorial">Factorial</button><button class="tab" data-view="recovery">State recovery</button><button class="tab" data-view="architecture">Joint SSM</button><button class="tab" data-view="validation">Validation</button><button class="tab" data-view="report">Report & code</button></nav><a class="reporttop" href="report/Signals_Project_APA_Report.pdf">Open 27-page report</a></div></header><main class="shell">
<section class="hero"><div><div class="eyebrow">Computational statistics · blind data fusion</div><h1>The joint torus SSM is now executed.</h1><p>Two overlapping frequency-hopping emitters are filtered jointly with latent complex multipath, true circular phase, switching dynamics, an exact Gaussian–truncated-Cauchy convolution likelihood, and exact-target torus MALA rejuvenation.</p></div><aside class="scope"><strong>Claim boundary</strong><br>This repository establishes <em>operationally representative simulation validation</em>. It does not claim field or operational SIGINT validation because no controlled receiver recordings, independently blinded truth set, or hardware-in-the-loop campaign is included.</aside></section>
<section id="overview" class="view active"><div class="kpis"><div class="card"><div class="kval">1,800</div><div class="klabel">Method runs</div></div><div class="card"><div class="kval">900</div><div class="klabel">Paired trajectories</div></div><div class="card"><div class="kval">18</div><div class="klabel">Factorial cells</div></div><div class="card"><div class="kval">64</div><div class="klabel">Joint particles</div></div><div class="card"><div class="kval">60</div><div class="klabel">I/Q samples / run</div></div></div><div class="panel"><h2>Population endpoint comparison</h2><p class="sub">Means across all 900 paired trajectories per architecture. Lower is better for errors and latency; higher is better for particle ESS.</p><div id="overviewChart" class="chart short" role="img" aria-label="Architecture endpoint comparison"></div><div class="grid3"><article class="method"><span class="tag">Primary accuracy</span><h3 id="mseHeadline"></h3><p id="mseText"></p></article><article class="method"><span class="tag">Compute</span><h3>Exact correction has a price</h3><p id="latencyText"></p></article><article class="method"><span class="tag">Inference geometry</span><h3>Joint, circular, and blind</h3><p>Every particle carries two amplitudes, frequencies, hop states, torus phases, complex channel taps, and the tapped-delay source history.</p></article></div></div><div class="panel"><h2>What changed from the spectral reference model</h2><div class="grid3"><article class="method"><span class="tag">Likelihood</span><h3>True convolution</h3><p>Gaussian and truncated-Cauchy noise are summed, then integrated by Gauss–Legendre quadrature in log space. No density floor is inserted.</p></article><article class="method"><span class="tag">Latent state</span><h3>Channel truth isolated</h3><p>The filter receives observations and calibrated noise hyperparameters—not the realized channel, phase, frequency, or hop path.</p></article><article class="method"><span class="tag">Proposal</span><h3>Flat-torus MALA</h3><p>Phase moves use tangent Gaussian increments, exponential retraction, and lift-summed wrapped forward/reverse densities.</p></article></div></div></section>
<section id="factorial" class="view"><div class="panel"><h2>Full 2 × 3 × 3 evidence explorer</h2><p class="sub">Select an endpoint and channel. Points show 100-run cell means with 95% normal intervals.</p><div class="controls"><label class="control">Endpoint<select id="metric"><option value="mse_frequency">Frequency MSE</option><option value="phase_circular_rmse">Circular phase RMSE</option><option value="channel_nmse">Channel NMSE</option><option value="particle_ess_mean">Particle ESS</option><option value="unique_ancestor_mean">Unique ancestors</option><option value="mala_acceptance">MALA acceptance</option><option value="latency_ms_per_sample">Latency / sample</option></select></label><label class="control">Channel<select id="channel"><option>All</option><option>LOS</option><option>MP</option><option>NLOS</option></select></label></div><div id="factorialChart" class="chart"></div></div><div class="grid2"><div class="panel"><h2>Paired architecture contrast</h2><p class="sub">Surrogate minus analytical; the zero line denotes no paired difference.</p><div id="contrastChart" class="chart short"></div></div><div class="panel"><h2>Cell evidence</h2><div class="scroll"><table id="cellTable"><thead><tr><th>Method</th><th>SNR</th><th>Channel</th><th>Freq. MSE</th><th>Phase</th><th>Channel</th><th>ESS</th></tr></thead><tbody></tbody></table></div></div></div><div class="panel"><h2>Blocked repeated-measures effects</h2><p class="sub">Multivariate orthonormal-contrast tests on log frequency MSE; trajectory seed is the repeated block. Holm adjustment covers the seven omnibus effects.</p><div class="scroll"><table id="effectTable"><thead><tr><th>Effect</th><th>df</th><th>F</th><th>p</th><th>Holm p</th><th>Partial η²</th></tr></thead><tbody></tbody></table></div></div></section>
<section id="recovery" class="view"><div class="panel"><h2>Predeclared NLOS state-recovery trace</h2><p class="sub">Seed 0, +5 dB, NLOS. This trace is fixed by the build script; population claims use every trajectory.</p><div class="controls"><label class="control">Emitter<select id="emitter"><option value="1">Emitter 1</option><option value="2">Emitter 2</option></select></label><label class="control">Method<select id="traceMethod"><option>Analytical joint score</option><option>Amortized joint surrogate</option></select></label></div><div id="traceChart" class="chart"></div></div><div class="grid2"><div class="panel"><h2>Torus phase recovery</h2><p class="sub">Angles are represented in [0,2π); error summaries use the shortest circular difference.</p><div id="phaseChart" class="chart short"></div></div><div class="panel"><h2>Sequential particle health</h2><p class="sub">ESS is the importance-weight diagnostic, not MCMC chain ESS. Unique-ancestor counts quantify resampling diversity.</p><div id="essChart" class="chart short"></div></div></div></section>
<section id="architecture" class="view"><div class="panel"><h2>Executed filtering recursion</h2><p class="sub">The same exact joint target corrects proposals from both score operators.</p><div class="pipeline"><div class="node"><span class="tag">1 · switch</span><b>Hop state z<sub>t</sub></b><small>Markov transition over overlapping channel alphabets.</small></div><div class="node"><span class="tag">2 · propagate</span><b>a<sub>t</sub>, f<sub>t</sub>, φ<sub>t</sub>, h<sub>t</sub></b><small>Mean-reverting amplitude, switching frequency, torus phase, AR complex taps.</small></div><div class="node"><span class="tag">3 · observe</span><b>Tapped-delay I/Q</b><small>Latent channel combines delayed complex emitter histories.</small></div><div class="node"><span class="tag">4 · weight</span><b>Exact convolution</b><small>Stable quadrature evaluates Gaussian plus truncated-Cauchy density.</small></div><div class="node"><span class="tag">5 · rejuvenate</span><b>Torus MALA</b><small>Analytical or amortized drift; exact MH correction and wrapped q.</small></div></div></div><div class="grid2"><div class="panel"><h2>Filtering target</h2><div class="formula">p(X<sub>t</sub>, φ<sub>t</sub>, h<sub>t</sub>, z<sub>t</sub> | y<sub>1:t</sub>) ∝ p(y<sub>t</sub>|X<sub>t</sub>,φ<sub>t</sub>,h<sub>t</sub>) p(X<sub>t</sub>,φ<sub>t</sub>,h<sub>t</sub>,z<sub>t</sub>|·)</div><p>The particle cloud is the filtering distribution. The realized simulator channel is retained only for post hoc NMSE evaluation.</p></div><div class="panel"><h2>Flat-torus proposal</h2><div class="formula">φ* = (φ + ½ε²s<sub>φ</sub> + εη) mod 2π<br>q<sub>T</sub>(φ*|φ) = Σ<sub>k∈Z</sub> N(φ*−φ+2πk; ½ε²s<sub>φ</sub>, ε²)</div><p>For the flat torus, the exponential-map Jacobian is one under Haar volume. The implemented finite lift sum is numerically exact at the configured proposal scale.</p></div></div><div class="panel"><h2>Score architectures</h2><div class="grid2"><article class="method"><span class="tag">Method 1</span><h3>Analytical joint score</h3><p>The likelihood score differentiates normalized quadrature weights; transition scores are closed-form, including candidate-dependent phase-to-frequency coupling.</p></article><article class="method"><span class="tag">Method 2</span><h3>Amortized joint surrogate</h3><p>An independently trained SiLU random-feature network predicts the full joint proposal score. The exact target and reverse proposal remain in the MH ratio.</p></article></div></div></section>
<section id="validation" class="view"><div class="panel"><h2>Validation ladder</h2><p class="sub">The repository marks completed evidence separately from evidence still required for an operational claim.</p><div class="grid3"><article class="method"><span class="status">✓ completed</span><h3>Numerical verification</h3><p>Convolution and wrapped densities normalize; analytical scores match central differences; torus periodicity and blind API constraints are tested.</p></article><article class="method"><span class="status">✓ completed</span><h3>Representative simulation</h3><p>1,800 executions span hopping, +15/+5/−5 dB, LOS/MP/NLOS tapped-delay channels, heavy tails, and both corrected proposals.</p></article><article class="method"><span class="status pending">○ required</span><h3>Operational validation</h3><p>Requires recorded complex I/Q, blinded emitter/channel truth, receiver calibration, hardware timing, scenario provenance, and independent replication.</p></article></div></div><div class="panel"><h2>Claim audit</h2><div class="scroll"><table><tbody><tr><th>Can claim</th><td>Executed blind joint SSM; exact configured noise law; torus-valued phase; latent tapped-delay channel; paired simulation effects.</td></tr><tr><th>Cannot claim yet</th><td>Validated intercept performance on real emitters, real receivers, uncontrolled spectrum, classified data, or hardware deployment.</td></tr><tr><th>Next gate</th><td>Pre-register field protocol, lock code/weights, acquire lawful controlled I/Q, blind analysts, score against independent truth, and replicate.</td></tr></tbody></table></div></div><div class="panel"><h2>Permanent regression suite</h2><div class="grid3"><div class="method"><span class="tag">Noise</span><h3>2 tests</h3><p>Density normalization and score finite-difference agreement.</p></div><div class="method"><span class="tag">Torus</span><h3>3 tests</h3><p>Haar normalization, wrapped-score agreement, and periodicity.</p></div><div class="method"><span class="tag">Joint filter</span><h3>4 tests</h3><p>Nyquist validity, all-coordinate score audit, blind-interface audit, and NLOS end-to-end smoke.</p></div></div></div></section>
<section id="report" class="view"><div class="panel"><h2>APA-style report and immutable evidence</h2><p class="sub">The 27-page report states the executed model, factorial estimands, measured results, limitations, and the protocol required before field-validation language is used.</p><a class="download" href="report/Signals_Project_APA_Report.pdf">Open PDF report</a><a class="download secondary" href="data/joint_factorial_results.csv" download>All 1,800 runs</a><a class="download secondary" href="data/joint_cell_summary.csv" download>Cell summaries</a><a class="download secondary" href="data/joint_factorial_effects.csv" download>Factorial tests</a></div><div class="panel"><h2>Reproduce</h2><div class="steps"><div class="step"><div><h3>Install</h3><div class="formula">python -m venv .venv<br>source .venv/bin/activate<br>pip install -r requirements.txt</div></div></div><div class="step"><div><h3>Verify numerical invariants</h3><div class="formula">PYTHONPATH=. python -m unittest discover -s tests -v</div></div></div><div class="step"><div><h3>Execute all 1,800 method runs</h3><div class="formula">PYTHONPATH=. python -m src.signals_project.joint_ssm --output data --repetitions 100 --particles 64 --samples 60<br>python scripts/analyze_joint_results.py</div></div></div><div class="step"><div><h3>Rebuild publication artifacts</h3><div class="formula">python scripts/build_site.py<br>python scripts/build_report.py</div></div></div></div></div><div class="panel"><h2>Machine-readable audit</h2><div class="scroll"><table><tbody><tr><th>Physical blocks</th><td id="physicalBlocks"></td></tr><tr><th>Surrogate training</th><td id="trainMeta"></td></tr><tr><th>Surrogate validation</th><td id="validMeta"></td></tr><tr><th>Validation scope</th><td id="scopeMeta"></td></tr></tbody></table></div></div></section>
<footer class="footer">Signals Project · Executed joint torus-valued SSM · Operationally representative simulation evidence only.</footer></main>
<script>
const cells=__CELLS__,pairs=__PAIRS__,trace=__TRACE__,effects=__EFFECTS__,meta=__META__;const methods=['Analytical joint score','Amortized joint surrogate'];const colors={'Analytical joint score':'#38d6ff','Amortized joint surrogate':'#ffc35c'};const base={paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#c6d2df',family:'Inter,system-ui,sans-serif'},margin:{l:72,r:28,t:28,b:58},xaxis:{gridcolor:'#24364a',zerolinecolor:'#38506a'},yaxis:{gridcolor:'#24364a',zerolinecolor:'#38506a'},legend:{orientation:'h',y:1.14}};const config={responsive:true,displaylogo:false,modeBarButtonsToRemove:['lasso2d','select2d']};
document.querySelectorAll('.tab').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.getElementById(btn.dataset.view).classList.add('active');setTimeout(()=>window.dispatchEvent(new Event('resize')),40)}));
const mean=(method,key)=>{const rows=cells.filter(x=>x.architecture===method);return rows.reduce((s,x)=>s+x[key],0)/rows.length};const endpointKeys=['mse_frequency_mean','phase_circular_rmse_mean','channel_nmse_mean','particle_ess_mean_mean','latency_ms_per_sample_mean'];const endpointLabels=['Frequency MSE','Phase RMSE','Channel NMSE','Particle ESS','Latency / sample'];const denom=endpointKeys.map(k=>mean(methods[0],k));Plotly.newPlot('overviewChart',methods.map(m=>({type:'bar',name:m,x:endpointLabels,y:endpointKeys.map((k,i)=>mean(m,k)/denom[i]),marker:{color:colors[m]},hovertemplate:'%{x}<br>ratio=%{y:.3f}<extra>%{fullData.name}</extra>'})),{...base,barmode:'group',height:390,yaxis:{...base.yaxis,title:'Ratio to analytical mean'}},config);
const overall=metric=>pairs.find(x=>x.group==='Overall'&&x.metric===metric);const md=overall('mse_frequency'),ld=overall('latency_ms_per_sample');document.getElementById('mseHeadline').textContent=md.ci95_low<=0&&md.ci95_high>=0?'No clear raw-scale difference':'Architecture difference detected';document.getElementById('mseText').textContent=`Surrogate − analytical: ${md.mean_difference_surrogate_minus_analytical.toFixed(2)} Hz²; 95% CI [${md.ci95_low.toFixed(2)}, ${md.ci95_high.toFixed(2)}].`;document.getElementById('latencyText').textContent=`The surrogate added ${ld.mean_difference_surrogate_minus_analytical.toFixed(3)} ms per I/Q sample; 95% CI [${ld.ci95_low.toFixed(3)}, ${ld.ci95_high.toFixed(3)}].`;
const labels={mse_frequency:'Frequency MSE (Hz²)',phase_circular_rmse:'Circular phase RMSE (rad)',channel_nmse:'Channel NMSE',particle_ess_mean:'Mean particle ESS',unique_ancestor_mean:'Mean unique ancestors',mala_acceptance:'MALA acceptance rate',latency_ms_per_sample:'Latency per sample (ms)'};
function aggregate(metric,method,snr,channel){const rows=cells.filter(x=>x.architecture===method&&x.snr_db===snr&&(channel==='All'||x.channel===channel));const mk=metric+'_mean',sk=metric+'_sd',n=rows.reduce((s,x)=>s+x.n,0);const mu=rows.reduce((s,x)=>s+x[mk]*x.n,0)/n;const pooled=Math.sqrt(rows.reduce((s,x)=>s+x[sk]*x[sk]*x.n,0)/n);return {mu,se:pooled/Math.sqrt(n)}}function updateFactorial(){const metric=document.getElementById('metric').value,channel=document.getElementById('channel').value;const plots=methods.map(method=>{const rows=[-5,5,15].map(snr=>aggregate(metric,method,snr,channel));return {type:'scatter',mode:'lines+markers',name:method,x:[-5,5,15],y:rows.map(x=>x.mu),error_y:{type:'data',array:rows.map(x=>1.96*x.se)},line:{color:colors[method],width:3},marker:{size:9},hovertemplate:'SNR %{x} dB<br>%{y:.4f}<extra>%{fullData.name}</extra>'}});Plotly.react('factorialChart',plots,{...base,xaxis:{...base.xaxis,title:'Nominal SNR (dB)',tickvals:[-5,5,15]},yaxis:{...base.yaxis,title:labels[metric]}},config);updateContrast(metric)}function updateContrast(metric){const rows=pairs.filter(x=>x.group==='SNR'&&x.metric===metric).sort((a,b)=>+a.level-+b.level);Plotly.react('contrastChart',[{type:'scatter',mode:'markers',x:rows.map(x=>x.mean_difference_surrogate_minus_analytical),y:rows.map(x=>`${x.level} dB`),error_x:{type:'data',symmetric:false,array:rows.map(x=>x.ci95_high-x.mean_difference_surrogate_minus_analytical),arrayminus:rows.map(x=>x.mean_difference_surrogate_minus_analytical-x.ci95_low)},marker:{color:'#ae91ff',size:11},hovertemplate:'%{y}<br>difference=%{x:.4f}<extra></extra>'}],{...base,height:390,xaxis:{...base.xaxis,title:`Surrogate − analytical: ${labels[metric]}`},shapes:[{type:'line',x0:0,x1:0,y0:-.5,y1:2.5,line:{color:'#8395a8',dash:'dot'}}]},config)}document.getElementById('metric').addEventListener('change',updateFactorial);document.getElementById('channel').addEventListener('change',updateFactorial);updateFactorial();
const tbody=document.querySelector('#cellTable tbody');cells.slice().sort((a,b)=>b.snr_db-a.snr_db||a.channel.localeCompare(b.channel)||a.architecture.localeCompare(b.architecture)).forEach(x=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${x.architecture.replace(' joint ',' ')}</td><td>${x.snr_db.toFixed(0)}</td><td>${x.channel}</td><td>${x.mse_frequency_mean.toFixed(1)}</td><td>${x.phase_circular_rmse_mean.toFixed(3)}</td><td>${x.channel_nmse_mean.toFixed(3)}</td><td>${x.particle_ess_mean_mean.toFixed(1)}</td>`;tbody.appendChild(tr)});const primary=effects.filter(x=>x.response==='mse_frequency');const et=document.querySelector('#effectTable tbody');const pf=x=>x<.001?'&lt; .001':x.toFixed(3).replace(/^0/,'');primary.forEach(x=>{const tr=document.createElement('tr');tr.innerHTML=`<td>${x.effect}</td><td>${x.df1}, ${x.df2}</td><td>${x.F.toFixed(2)}</td><td>${pf(x.p_value)}</td><td>${pf(x.p_holm_within_response)}</td><td>${x.partial_eta_squared.toFixed(3)}</td>`;et.appendChild(tr)});
function updateTrace(){const emitter=document.getElementById('emitter').value,method=document.getElementById('traceMethod').value,rows=trace.filter(x=>x.architecture===method).sort((a,b)=>a.sample-b.sample);Plotly.react('traceChart',[{type:'scatter',mode:'lines',name:'True frequency',x:rows.map(x=>x.sample),y:rows.map(x=>x[`true_f${emitter}_hz`]),line:{shape:'hv',color:'#e8f1fb',width:3}},{type:'scatter',mode:'lines+markers',name:'Filtered mean',x:rows.map(x=>x.sample),y:rows.map(x=>x[`inferred_f${emitter}_hz`]),line:{color:colors[method],width:2},marker:{size:5}}],{...base,xaxis:{...base.xaxis,title:'I/Q sample'},yaxis:{...base.yaxis,title:'Frequency (Hz)'}},config);Plotly.react('phaseChart',[{type:'scatter',mode:'markers',name:'True phase',x:rows.map(x=>x.sample),y:rows.map(x=>x.true_phase1),marker:{color:'#e8f1fb',size:5}},{type:'scatter',mode:'markers',name:'Filtered phase',x:rows.map(x=>x.sample),y:rows.map(x=>x.inferred_phase1),marker:{color:colors[method],size:5}}],{...base,height:390,xaxis:{...base.xaxis,title:'I/Q sample'},yaxis:{...base.yaxis,title:'Phase (rad)',range:[0,6.283]}},config);Plotly.react('essChart',[{type:'scatter',mode:'lines',name:'Particle ESS',x:rows.map(x=>x.sample),y:rows.map(x=>x.particle_ess),fill:'tozeroy',line:{color:'#65e6aa'}}],{...base,height:390,xaxis:{...base.xaxis,title:'I/Q sample'},yaxis:{...base.yaxis,title:'ESS',range:[0,66]}},config)}document.getElementById('emitter').addEventListener('change',updateTrace);document.getElementById('traceMethod').addEventListener('change',updateTrace);updateTrace();document.getElementById('physicalBlocks').textContent=`${meta.unique_physical_trajectories} paired blocks; ${meta.experimental_rows} method-level rows`;document.getElementById('trainMeta').textContent=`${meta.surrogate_validation.training_rows} independent rows`;document.getElementById('validMeta').textContent=`score correlation ${meta.surrogate_validation.validation_score_correlation.toFixed(3)}; RMSE ${meta.surrogate_validation.validation_score_rmse.toFixed(3)}`;document.getElementById('scopeMeta').textContent=meta.validation_scope;
</script></body></html>'''
